// 20-11-2026 19:21 · Germán (captura de «Hoy en 60 segundos» con la ficha de Marejadas encerrada y «RESUMIR»): «De las fichas que
// aparecen en la portada del Newsletter, como es una mirada rápida de los principales temas, debes resumir el texto!!».
// Cada ficha (.chip60) es un vistazo: la Skill a veces copia ahí el aviso completo (zona, días, horas, emisión) y la tarjeta crece
// hasta doblar a las otras. Aquí, al pasar la página, toda ficha de más de 80 letras se resume en una línea corta; el detalle completo
// sigue en su sección (la ficha es un enlace a ella). Las marejadas se resumen como «Aviso vigente · zona · hasta el lunes 23», con su
// versión en inglés; cualquier otra ficha larga se corta en su primera frase. Las fichas cortas pasan intactas, byte por byte.
const MAX60 = 80;
const DIAS_EN = { lunes: "Monday", martes: "Tuesday", "miércoles": "Wednesday", jueves: "Thursday", viernes: "Friday", "sábado": "Saturday", domingo: "Sunday" };
const NEGRITA_EN = { "aviso vigente": "Warning in effect", "alerta vigente": "Alert in effect", "sin avisos": "No warnings" };
const esc60 = (s) => String(s).replace(/&(?!(?:[a-z]+|#\d+|#x[\da-f]+);)/gi, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const plano = (s) => String(s).replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/\s+/g, " ").trim();

function cortar(t, n) {
  if (t.length <= n) return t;
  const c = t.slice(0, n + 1).replace(/[\s,;:·-]+\S*$/, "");
  return (c || t.slice(0, n)).replace(/[\s,;:·-]+$/, "") + "…";
}

// segs: [[negrita, texto crudo]] en orden. Devuelve el HTML de la ficha (igual al original si es corta).
function resumir60(segs) {
  const crudo = segs.map(([b, t]) => (b ? `<b>${t}</b>` : t)).join("").replace(/<\/b><b>/g, "");
  const todo = plano(segs.map((s) => s[1]).join(""));
  if (todo.length <= MAX60) return { html: crudo };
  const i = segs.findIndex((s) => s[0]);
  const neg = i >= 0 ? plano(segs.filter((s) => s[0]).map((s) => s[1]).join("")) : "";
  const resto = plano(segs.filter((s) => !s[0]).map((s) => s[1]).join("")).replace(/^[\s·,:;-]+/, "");
  if (/marejada/i.test(resto)) {
    const z = resto.match(/:\s*([^,;]+?)\s*(?:,|;|$)/);
    const h = resto.match(/\bal\s+(lunes|martes|mi[eé]rcoles|jueves|viernes|s[aá]bado|domingo)\s+(\d{1,2})\b/i);
    if (z) {
      const zona = z[1].replace(/\s+hasta\s+/i, " a ").replace(/Archipi[eé]lago\s+(de\s+)?Juan Fern[aá]ndez/i, "J. Fernández").trim();
      const dia = h ? h[1].toLowerCase().replace("miercoles", "miércoles").replace("sabado", "sábado") : "";
      const es = `${neg ? `<b>${esc60(neg)}</b> · ` : ""}${esc60(cortar(zona, 52))}${h ? ` · hasta el ${dia} ${h[2]}` : ""}`;
      const negEn = NEGRITA_EN[neg.toLowerCase()] || "";
      const zonaEn = zona.replace(/\s+a\s+/, " to ").replace(/Golfo de /g, "Gulf of ").replace(/\s+y\s+/g, " and ");
      const en = negEn ? `<b>${esc60(negEn)}</b> · ${esc60(cortar(zonaEn, 52))}${h ? ` · until ${DIAS_EN[dia] || dia} ${h[2]}` : ""}` : "";
      return { html: es, en, completo: todo };
    }
  }
  const frase = resto.split(/\s*(?:;|\s\(|\.\s)/)[0];
  const n = Math.max(24, MAX60 - (neg ? neg.length + 3 : 0));
  return { html: `${neg ? `<b>${esc60(neg)}</b> · ` : ""}${esc60(cortar(frase, n))}`, completo: todo };
}

function sesenta() {
  let segs = null, negrita = false;
  return {
    v: {
      element(e) {
        segs = []; negrita = false;
        e.onEndTag((fin) => {
          const s = segs; segs = null;
          if (!s || !s.length) return;
          const r = resumir60(s);
          const html = r.en
            ? `<span class="cn60" data-no-tr translate="no" data-en="${esc60(r.en)}">${r.html}</span>`
            : r.html;
          fin.before(html, { html: true });
        });
      },
      text(t) { if (segs) { if (t.text) segs.push([negrita, t.text]); t.remove(); } },
    },
    b: { element(e) { if (!segs) return; negrita = true; e.removeAndKeepContent(); e.onEndTag(() => { negrita = false; }); } },
    cuerpo: { element(e) { e.append(SESENTA_JS, { html: true }); } },
  };
}

// Las fichas resumidas con versión en inglés siguen al botón ES/EN como el resto de la edición.
const SESENTA_JS = `<script>(function(){var E=[].slice.call(document.querySelectorAll('.cn60[data-en]'));if(!E.length)return;
E.forEach(function(e){e.setAttribute('data-es',e.innerHTML)});
function f(l){var en=/^en/i.test(String(l||''));E.forEach(function(e){var t=e.getAttribute(en?'data-en':'data-es');if(t!=null&&e.innerHTML!==t)e.innerHTML=t})}
f(document.documentElement.lang);document.addEventListener('cofrade-idioma',function(e){f(e.detail)})})();<\/script>`;

// 20-11-2026 19:17 · Germán: en «9. Indicadores económicos», «al clickear encima con el cursor deberá aparecer una ventana emergente con
// un gráfico que muestre todas las variaciones que ese indicador ha experimentado en el mes, similar al diseño de los gráficos que
// aparecen al comienzo del Newsletter en la sección "Indicadores y monedas"».
// Cada tarjeta se vuelve un botón (mouse, dedo o teclado) que abre una ventana con el gráfico, en el dorado de «Indicadores y monedas».
// Datos, siempre de la misma fuente que la tarjeta y nunca inventados:
//  · Diarios (UF, dólar, euro, cobre, TPM): el último mes del Banco Central (datos/historia.json, que el robot de datos baja cada 30 min).
//  · Mensuales (UTM, IPC del mes, IPC 12 meses): los últimos 13 meses del Banco Central (misma historia; si aún no están, mindicador.cl).
//    Un dato mensual no varía dentro del mes: por eso se muestra su recorrido de 13 meses, y la ventana lo dice.
//  · IMACEC y desempleo: los últimos 13 meses de mindicador.cl (Banco Central e INE), la misma fuente que cita la tarjeta.
//  · Bitcoin: el último mes de cierres diarios de Coinbase (la fuente de la tarjeta).
// Si una fuente no responde, la ventana lo dice en una línea; nunca dibuja una serie inventada ni rellena huecos.
const IND = {
  uf: { n: "UF", en: "UF", h: "uf", pre: "$", dec: 2, f: "Banco Central de Chile" },
  dolar: { n: "Dólar observado", en: "Observed dollar", h: "dolar", pre: "$", dec: 2, f: "Banco Central de Chile" },
  euro: { n: "Euro", en: "Euro", h: "euro", pre: "$", dec: 2, f: "Banco Central de Chile" },
  cobre: { n: "Libra de cobre", en: "Copper (per pound)", h: "cobre", pre: "US$", dec: 2, f: "Banco Central de Chile" },
  tpm: { n: "TPM", en: "Monetary policy rate", h: "tpm", suf: "%", dec: 2, f: "Banco Central de Chile", pp: 1 },
  utm: { n: "UTM", en: "UTM", h: "utm", md: "utm", pre: "$", dec: 0, f: "Banco Central de Chile", mes: 1 },
  ipc: { n: "IPC del mes", en: "CPI, monthly change", h: "ipc", md: "ipc", suf: "%", dec: 1, f: "Banco Central de Chile", mes: 1, pp: 1 },
  ipc12: { n: "IPC 12 meses", en: "CPI, 12-month change", h: "ipc12", suf: "%", dec: 1, f: "Banco Central de Chile", mes: 1, pp: 1 },
  imacec: { n: "IMACEC", en: "IMACEC", h: "imacec", md: "imacec", suf: "%", dec: 1, f: "Banco Central de Chile", mes: 1, pp: 1 },   // 24-11-2026: serie del Banco Central (con revisiones); mindicador, de respaldo
  desempleo: { n: "Desempleo", en: "Unemployment", md: "tasa_desempleo", suf: "%", dec: 1, f: "INE vía mindicador.cl", mes: 1, pp: 1 },
  bitcoin: { n: "Bitcoin", en: "Bitcoin", pre: "US$", dec: 0, f: "Coinbase", cb: 1 },
};

async function traerJson(url, ttl) {
  const r = await fetch(url, { headers: { "User-Agent": "CofradeNews/1.0 (+https://www.cofrad.es)", Accept: "application/json" },
    cf: { cacheTtl: ttl, cacheEverything: true }, signal: AbortSignal.timeout(7000) });
  if (!r.ok) throw new Error("http " + r.status);
  return r.json();
}

const diaIso = (f) => String(f || "").slice(0, 10);
function ultimoMes(p) {   // del mismo día del mes anterior al último dato, hasta el último dato
  if (!p.length) return p;
  const u = new Date(p[p.length - 1][0] + "T12:00:00Z");
  u.setUTCMonth(u.getUTCMonth() - 1);
  const d = u.toISOString().slice(0, 10);
  return p.filter((x) => x[0] >= d);
}

async function apiIndicador(k, h) {
  const c = IND[k];
  if (!c) return { error: "indicador desconocido" };
  let p = [], fuente = c.f;
  const S = (h && h.series) || {};
  if (c.h && S[c.h] && Array.isArray(S[c.h].datos) && S[c.h].datos.length > 1) {
    p = S[c.h].datos.map((x) => [diaIso(x[0]), Number(x[1])]).filter((x) => isFinite(x[1]));
  } else if (c.md) {
    const j = await traerJson(`https://mindicador.cl/api/${c.md}`, 3600).catch(() => null);
    p = ((j && j.serie) || []).map((x) => [diaIso(x.fecha), Number(x.valor)]).filter((x) => x[0] && isFinite(x[1]));
    fuente = c.md === "tasa_desempleo" ? c.f : (c.h ? "Banco Central de Chile vía mindicador.cl" : c.f);
  } else if (c.cb) {
    const j = await traerJson("https://api.exchange.coinbase.com/products/BTC-USD/candles?granularity=86400", 1800).catch(() => null);
    p = (Array.isArray(j) ? j : []).map((x) => [new Date(x[0] * 1000).toISOString().slice(0, 10), Number(x[4])]).filter((x) => isFinite(x[1]));
  }
  p.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  p = p.filter((x, i) => i === 0 || x[0] !== p[i - 1][0]);
  p = c.mes ? p.slice(-13) : ultimoMes(p);
  if (p.length < 2) return { error: "sin datos" };
  // Una fuente atrasada no se muestra como si fuera de hoy (20-11-2026: mindicador.cl seguía con el IPC de diciembre de 2025).
  const dias = p.length ? (Date.now() - Date.parse(p[p.length - 1][0] + "T12:00:00Z")) / 864e5 : 1e9;
  if (dias > (c.mes ? 130 : 20)) return { error: "fuente atrasada" };
  return { k, nombre: c.n, nombre_en: c.en, pre: c.pre || "", suf: c.suf || "", dec: c.dec, mensual: !!c.mes, pp: !!c.pp, fuente, puntos: p };
}

